export function freshName138(key,extra=[]){const used=new Set([...Object.values(PEOPLE_NAMES138),...extra.map(cleanName138)]);let h=2166136261;for(const c of key)h=Math.imul(h^c.charCodeAt(0),16777619);for(let i=0;i<pool.length;i++){const name=pool[((h>>>0)+i)%pool.length];if(!used.has(name))return name;}const syllables='ア イ ウ エ オ カ キ ク ケ コ サ シ ス セ ソ タ チ ツ テ ト ナ ニ ヌ ネ ノ ハ ヒ フ ヘ ホ マ ミ ム メ モ ヤ ユ ヨ ラ リ ル レ ロ ワ'.split(' ');for(let i=0;i<syllables.length**3;i++){let v=((h>>>0)+i)%(syllables.length**3);const name=Array.from({length:3},()=>{const c=syllables[v%syllables.length];v=Math.floor(v/syllables.length);return c;}).join('');if(!used.has(name))return name;}throw new Error('名前の候補が不足しています。');}
